-- Row count check (expected: 5, 10, 3, 3, 50, 100, 100, 100, 100)
SELECT 'department' AS tbl, COUNT(*) AS row_count FROM department
UNION ALL SELECT 'positions', COUNT(*) FROM positions
UNION ALL SELECT 'disability', COUNT(*) FROM disability
UNION ALL SELECT 'order_name_list', COUNT(*) FROM order_name_list
UNION ALL SELECT 'order_list', COUNT(*) FROM order_list
UNION ALL SELECT 'employee_list', COUNT(*) FROM employee_list
UNION ALL SELECT 'contract', COUNT(*) FROM contract
UNION ALL SELECT 'contract_appendix', COUNT(*) FROM contract_appendix
UNION ALL SELECT 'employee_attendance', COUNT(*) FROM employee_attendance;
